rows.command:
# This command reads the worktree; refuse to run unless the tree is exactly $SHA.
git diff --quiet "$SHA" -- || { echo "worktree is not at $SHA" >&2; exit 1; }
node scripts/docs/covers-gaps.mjs 2>&1 | sed -nE 's/.*\(([0-9]+) baselined pair\(s\) across ([0-9]+) doc\(s\) remain\).*/\1\n\2/p'

# This command reads the worktree; refuse to run unless the tree is exactly $SHA.
git diff --quiet "$SHA" -- || { echo "worktree is not at $SHA" >&2; exit 1; }
"$RG" -c ': any\b|as any' packages/*/src --type ts -g '!*test*' | awk -F: '{s+=$2} END{print s+0}'

# This command reads the worktree; refuse to run unless the tree is exactly $SHA.
git diff --quiet "$SHA" -- || { echo "worktree is not at $SHA" >&2; exit 1; }
node scripts/db-mock-ratchet.mjs 2>&1 | sed -nE 's/^db-mock gauge: ([0-9]+) db\.js mock\(s\) and ([0-9]+) positional mockResolvedValueOnce call\(s\) across ([0-9]+) test file\(s\)\..*/\1\n\2\n\3/p'

# This command reads the worktree; refuse to run unless the tree is exactly $SHA.
git diff --quiet "$SHA" -- || { echo "worktree is not at $SHA" >&2; exit 1; }
"$RG" -l "from 'zod'" packages/backend/src | wc -l

# This command reads the worktree; refuse to run unless the tree is exactly $SHA.
git diff --quiet "$SHA" -- || { echo "worktree is not at $SHA" >&2; exit 1; }
"$RG" -l "from '" packages/backend/src | wc -l

